    @if($canReadActivity)<section class="card overflow-x-auto"><h2 class="text-lg font-semibold mb-4">Últimas pruebas y mensajes de la cuenta</h2><table class="w-full text-sm text-left"><thead class="text-slate-500 border-b border-slate-100"><tr><th class="pb-3">Mensaje</th><th class="pb-3">Resultado</th><th class="pb-3"><span class="sr-only">Archivo</span></th></tr></thead><tbody class="divide-y divide-slate-100">@forelse($messages as $message)<tr wire:key="mail-message-{{ $message->id }}"><td class="py-4 pr-4"><p class="font-semibold">{{ $message->subject }}</p><p class="text-xs text-slate-500 mt-2">{{ $message->sender_email }} → {{ $message->recipient }}</p></td><td class="py-4 pr-4">{{ ['sending'=>'Transporte iniciado; resultado pendiente','suppressed'=>'Destinatario suprimido; sin transporte','preparing'=>'Preparando','logged'=>'Log privado; sin conexión SMTP','smtp_accepted'=>'SMTP aceptado; entrega no acreditada','smtp_unconfirmed'=>'Aceptación SMTP incierta; no reenviar automáticamente','local_failed'=>'No se pudo guardar el archivo','blocked'=>'Correo externo bloqueado'][$message->status] ?? 'Estado no disponible' }}</td><td class="py-4 text-right">@if($message->artifact_path)<a class="text-indigo-600" href="{{ route('mail-artifacts.download', $message->id) }}">Descargar .eml</a>@endif</td></tr>@empty<tr><td colspan="3" class="py-6 text-slate-500">Todavía no hay pruebas registradas.</td></tr>@endforelse</tbody></table><div class="mt-4">{{ $messages->links() }}</div></section>@endif
